(function(){
  var b=document.body, btn=document.querySelector('.burger'), dr=document.getElementById('drawer'), top=document.querySelector('.top');
  function setOpen(o){b.classList.toggle('open',o);dr.hidden=!o;btn.setAttribute('aria-expanded',o);btn.setAttribute('aria-label',o?'Tancar el menú':'Obrir el menú');}
  btn.addEventListener('click',function(){setOpen(dr.hidden);});
  dr.addEventListener('click',function(e){if(e.target.closest('a'))setOpen(false);});
  document.addEventListener('keydown',function(e){if(e.key==='Escape'&&!dr.hidden)setOpen(false);});
  function check(){
    var big=document.querySelector('.page:not([hidden]) .hero .giant')||document.querySelector('.page:not([hidden]) .hero');
    var compact=false;
    if(big){var end=big.getBoundingClientRect().bottom;compact=end>top.offsetHeight;}
    b.classList.toggle('compact',compact);
  }
  window.addEventListener('scroll',check,{passive:true});
  window.addEventListener('resize',check);
  window.addEventListener('hashchange',function(){setOpen(false);setTimeout(check,0);});
  check();
})();


(function(){
  var chips=[].slice.call(document.querySelectorAll('.pf .chip')),works=[].slice.call(document.querySelectorAll('.pf .work')),empty=document.querySelector('.pf .empty'),q=document.getElementById('pfq'),cur='all';
  function norm(t){return (t||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'');}
  function apply(){var term=norm((q?q.value:"").trim()),n=0;works.forEach(function(w){var okc=cur==='all'||(' '+w.getAttribute('data-cat')+' ').indexOf(' '+cur+' ')>-1;var okt=!term||norm(w.textContent).indexOf(term)>-1;var show=okc&&okt;w.hidden=!show;if(show)n++;});empty.hidden=n>0;}
  var wrap=document.querySelector('.pf .cards.works');
  function shuffle(){if(!wrap)return;var a=[].slice.call(wrap.children);for(var i=a.length-1;i>0;i--){var j=Math.floor(Math.random()*(i+1));var t=a[i];a[i]=a[j];a[j]=t;}var fr=document.createDocumentFragment();a.forEach(function(n){fr.appendChild(n);});wrap.appendChild(fr);}
  shuffle();
  chips.forEach(function(c){c.addEventListener('click',function(){cur=c.getAttribute('data-filter');chips.forEach(function(x){var on=x===c;x.classList.toggle('on',on);x.setAttribute('aria-pressed',on);});if(cur==='all')shuffle();apply();});});
  if(q)q.addEventListener('input',apply);
})();

