/* Efecte del logo de la web antiga (src/lib/actions/mutations.ts), portat a JS pla */
(function(){
  var maxDistanceFactor = 0.2;
  function getRandomColor(){
    var colors = ['#387b4f', '#334c80', '#c43e2f', '#f7de50', '#387b4f', '#c43e2f'];
    return colors[Math.floor(Math.random() * colors.length)];
  }
  function mutation(node){
    [].forEach.call(node.querySelectorAll('span'), function(span){
      var wrapper = document.createElement('span');
      wrapper.style.position = 'relative';
      wrapper.style.display = 'inline-block';
      span.parentNode.insertBefore(wrapper, span);
      wrapper.appendChild(span);
      span.style.display = 'inline-block';

      var shape = null;

      wrapper.addEventListener('mouseenter', function(){
        if (shape) return;

        var size = Math.random() * 100 + 30;
        shape = document.createElement('div');

        shape.style.position = 'absolute';
        shape.style.left = '50%';
        shape.style.top = '50%';
        shape.style.transform = 'translate(-50%, -50%)';
        shape.style.width = size + 'px';
        shape.style.height = size + 'px';
        shape.style.zIndex = '10';
        shape.style.backgroundColor = getRandomColor();
        shape.style.transition = 'transform 0.6s ease, opacity 0.6s ease';
        shape.style.opacity = '1';
        shape.style.pointerEvents = 'none';

        switch (Math.floor(Math.random() * 3)) {
          case 0: shape.style.borderRadius = '50%'; break;
          case 1: shape.style.borderRadius = '0'; break;
          case 2: shape.style.clipPath = 'polygon(50% 0%, 0% 100%, 100% 100%)'; break;
        }

        document.body.appendChild(shape);

        var rect = wrapper.getBoundingClientRect();
        var centerX = rect.left + rect.width / 2;
        var centerY = rect.top + rect.height / 2 + window.scrollY;
        shape.style.left = centerX + 'px';
        shape.style.top = centerY + 'px';
        shape.style.transform = 'translate(-50%, -50%) scale(1)';

        span.style.color = 'white';

        requestAnimationFrame(function(){
          var maxX = window.innerWidth * maxDistanceFactor;
          var maxY = window.innerHeight * maxDistanceFactor;
          var dx = (Math.random() - 0.5) * 2 * maxX;
          var dy = (Math.random() - 0.5) * 2 * maxY;
          var scale = Math.random() * 2 + 1;
          shape.style.transform = 'translate(' + dx + 'px, ' + dy + 'px) scale(' + scale + ')';
        });

        wrapper.addEventListener('mouseleave', function(){
          var sh = shape;
          if (!sh) return;
          setTimeout(function(){
            sh.style.transform = 'translate(-50%, -50%) scale(1)';
            sh.style.opacity = '0';
            span.style.color = '';
            setTimeout(function(){ sh.remove(); shape = null; }, 600);
          }, 1000);
        }, { once: true });
      });
    });
  }
  function mutationText(node){
    var txt = node.textContent || '';
    node.textContent = '';
    for (var i = 0; i < txt.length; i++) {
      var sp = document.createElement('span');
      sp.textContent = txt[i];
      node.appendChild(sp);
    }
    mutation(node);
  }

  var h = document.querySelector('.hero .giant');
  if (h) mutation(h);

  /* Paraules grans Creativitat / Tecnologia: mateix efecte de peces */
  [].forEach.call(document.querySelectorAll('.pil .word'), function(w){ mutationText(w); });
  var f = document.querySelector('.site-foot .flogo');
  if (f) mutation(f);

  /* Subtitol: accio random_position de la web antiga */
  function random_position(node, opts){
    opts = opts || {};
    var offsetPosition = opts.offsetPosition || 0,
        offsetScale = opts.offsetScale || 0,
        offsetRotation = opts.offsetRotation || 0;

    var walker = document.createTreeWalker(node, NodeFilter.SHOW_TEXT, null);
    var textNodes = [], current;
    while (walker.nextNode()) {
      current = walker.currentNode;
      if ((current.nodeValue && current.nodeValue.trim()) || current.nodeValue === ' ') textNodes.push(current);
    }

    textNodes.forEach(function(textNode){
      var parent = textNode.parentElement;
      if (!parent) return;
      var fragment = document.createDocumentFragment();
      var chars = textNode.nodeValue.split('');

      chars.forEach(function(char){
        var span = document.createElement('span');
        span.textContent = char;
        span.style.display = 'inline-block';
        span.style.transition = 'transform 0.4s ease';
        span.style.willChange = 'transform';
        if (char === ' ') span.style.width = '0.25em';

        var active = false;
        span.addEventListener('mouseenter', function(){
          if (active) return;
          active = true;
          var dx = (Math.random() - 0.5) * (80 + offsetPosition);
          var dy = (Math.random() - 0.5) * (80 + offsetPosition);
          var scale = 0.8 + Math.random() * (1.2 + offsetScale);
          var rotate = (Math.random() - 0.5) * (60 + offsetRotation);
          span.style.transform = 'translate(' + dx + 'px, ' + dy + 'px) scale(' + scale + ') rotate(' + rotate + 'deg)';

          span.addEventListener('transitionend', function onEnd(){
            span.removeEventListener('transitionend', onEnd);
            requestAnimationFrame(function(){
              requestAnimationFrame(function(){
                span.style.transform = 'translate(0px, 0px) scale(1) rotate(0deg)';
                span.addEventListener('transitionend', function(){ active = false; }, { once: true });
              });
            });
          }, { once: true });
        });

        fragment.appendChild(span);
      });

      parent.replaceChild(fragment, textNode);
    });
  }
  var sub = document.querySelector('.hero .lede');
  if (sub) random_position(sub, { offsetPosition: 100, offsetScale: 1 });

  /* Mateix efecte a tots els sobretitols i etiquetes de seccio */
  [].forEach.call(document.querySelectorAll('.h > span, .colhead .m, .pt .m, .teamlab, .mqtitle, .card .k, .labx .k, .flegal > span'), function(el){
    if (el.querySelector('a, b, strong, i, span, img')) return;
    if (!(el.textContent || '').trim()) return;
    random_position(el, { offsetPosition: 100, offsetScale: 1 });
  });

})();


/* Aparicio suau dels elements en fer scroll */
(function(){
  if (!('IntersectionObserver' in window)) return;
  if (window.matchMedia && matchMedia('(prefers-reduced-motion:reduce)').matches) return;

  var SEL = [
    '.pt > *', '.s > .h', '.s > .two > *', '.s > .three > div', '.s > .cards > *',
    '.colhead > *', '.pillars > .pil', '.plist li', '.pics figure', '.lap > div',
    '.labx > div', '.team > div', '.doc', '.rows li', '.svc li', '.ethic > div',
    '.cform > *', '.marquee', '.logos.wall', '.mqtitle', '.teamlab', '.owngrid > *', '.next',
    '.plinks', '.allbtn', '.lg', '.empty'
  ].join(',');

  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
    });
  }, { rootMargin: '0px 0px -8% 0px', threshold: 0.06 });

  function prep(root){
    var els = root.querySelectorAll(SEL);
    [].forEach.call(els, function(el){
      if (el.closest('.castle') || el.closest('.noreveal') || el.classList.contains('rv')) return;
      el.classList.add('rv');
      var sibs = el.parentElement ? [].indexOf.call(el.parentElement.children, el) : 0;
      el.style.transitionDelay = Math.min(sibs, 6) * 70 + 'ms';
      io.observe(el);
    });
  }

  function run(){
    var page = document.querySelector('.page:not([hidden])');
    if (page) prep(page);
    var foot = document.querySelector('.site-foot');
    if (foot && !foot.dataset.rvDone){ foot.dataset.rvDone = '1'; prep(foot); }
  }

  window.addEventListener('hashchange', function(){ setTimeout(run, 30); });
  if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', run);
  else run();
})();


/* Videos de YouTube: es carreguen nomes a la pagina visible, en silenci i sense controls */
(function(){
  function params(id,start,sound){var u="https://www.youtube-nocookie.com/embed/"+id+"?autoplay=1&mute="+(sound?0:1)+"&controls=0&loop=1&playlist="+id+"&modestbranding=1&rel=0&playsinline=1&disablekb=1";if(start) u+="&start="+start; return u;}
  function sync(){
    [].forEach.call(document.querySelectorAll("iframe.yt"), function(f){
      var pg = f.closest(".page");
      var visible = !pg || !pg.hasAttribute("hidden");
      if (visible && !f.src) {
        f.src = params(f.getAttribute("data-yt"), f.getAttribute("data-start"), true);
        var wrap = f.parentElement;
        if (wrap && !wrap.querySelector(".ytsound")) {
          var btn = document.createElement("button");
          btn.type = "button"; btn.className = "ytsound"; btn.setAttribute("aria-label", "Silenciar");
          btn.className = "ytsound on"; btn.innerHTML = '<span class="ytsi" aria-hidden="true">\u266A</span><span class="ytst">Silenci</span>';
          btn.addEventListener("click", function(){
            var on = btn.classList.toggle("on");
            btn.querySelector(".ytst").textContent = on ? "Silenci" : "So";
            btn.setAttribute("aria-label", on ? "Silenciar" : "Activar el so");
            f.src = params(f.getAttribute("data-yt"), f.getAttribute("data-start"), on);
          });
          wrap.appendChild(btn);
        }
      }
      else if (!visible && f.src) f.removeAttribute("src");
    });
  }
  window.addEventListener("hashchange", function(){ setTimeout(sync, 40); });
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", sync); else sync();
})();


/* Previsualitzacio de webs: carrega nomes la pagina visible */
